// A autenticação é feita no nó "Mensagem recebida" (Header Auth: x-webhook-token).
// Eventos sem o token certo nem chegam aqui.

const INSTANCIA = 'assistente';   // fixa: não confia no nome de instância que vem no corpo

// 1) Dados que a Evolution mandou
const body = $input.first().json.body || {};
const data = body.data || {};
const key = data.key || {};
const jid = key.remoteJid || '';

// 2) Só DMs de outras pessoas
if (body.event && body.event !== 'messages.upsert') return [];      // outros eventos
if (key.fromMe) return [];                                           // mensagem sua ou da IA (evita loop)
if (!jid || jid.endsWith('@g.us') || jid.includes('broadcast') || jid.endsWith('@newsletter')) return []; // grupos, status, canais

// 3) Número real: contatos novos podem vir como "...@lid" (ID interno do WhatsApp)
const jidReal = (jid.endsWith('@lid') && (key.remoteJidAlt || key.senderPn)) || jid;
// Só aceita telefone válido: impede injeção nas consultas e envios seguintes
if (!/^\d{8,15}@s\.whatsapp\.net$/.test(jidReal)) return [];
const numero = jidReal.split('@')[0];

// 4) Texto da mensagem (texto simples ou com formatação/resposta)
const m = data.message || {};
const texto = (m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || '').trim();
if (!texto) return [];                                               // áudio, foto, figurinha... por enquanto ignora

const nome = (data.pushName || '').trim().split(' ')[0];
const agora = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'full', timeStyle: 'short' }).format(new Date());

// "forcar: true" no corpo = reenvio manual que ignora a pausa (também precisa do token)
const forcar = body.forcar === true;

return [{ json: { msgId: String(key.id || ''), jid: jidReal, numero, nome, texto, agora, forcar, instancia: INSTANCIA } }];

// Junta o histórico do chat, decide se a IA deve responder e monta o contexto.
const f = $('Filtrar DM e extrair texto').first().json;
const a = ($('Histórico do contato').first().json.messages || {}).records || [];
const b = ($('Histórico da IA').first().json.messages || {}).records || [];

// 1) Junta as duas buscas sem repetir e ordena da mais antiga para a mais nova
const porId = {};
for (const r of [...a, ...b]) porId[r.key.id] = r;
const msgs = Object.values(porId).sort((x, y) => Number(x.messageTimestamp) - Number(y.messageTimestamp));

const textoDe = (r) => {
  const m = r.message || {};
  if (m.conversation) return m.conversation;
  if (m.extendedTextMessage && m.extendedTextMessage.text) return m.extendedTextMessage.text;
  if (m.imageMessage) return '[foto]' + (m.imageMessage.caption ? ' ' + m.imageMessage.caption : '');
  if (m.videoMessage) return '[vídeo]' + (m.videoMessage.caption ? ' ' + m.videoMessage.caption : '');
  if (m.audioMessage) return '[áudio]';
  if (m.stickerMessage) return '[figurinha]';
  if (m.documentMessage) return '[documento]';
  return '';
};
// A IA envia pela API: sem "addressingMode" e com source "web".
// Mensagem do Salatiel vem sincronizada do celular: tem "addressingMode" ou source ios/android.
const quem = (r) => {
  if (!r.key.fromMe) return 'contato';
  if (r.key.addressingMode || r.source === 'ios' || r.source === 'android') return 'salatiel';
  return 'assistente';
};

// 2) Agrupar: se o contato mandou outra mensagem de texto depois desta, deixa a execução dela responder
const recebidas = msgs.filter((r) => quem(r) === 'contato' && textoDe(r) && !textoDe(r).startsWith('['));
const ultima = recebidas[recebidas.length - 1];
if (ultima && ultima.key.id !== f.msgId) return [];

// 3) Pausa: se o Salatiel escreveu neste chat nos últimos minutos, a IA fica quieta
//    (reenvio manual com "forcar" ignora a pausa)
const PAUSA_MINUTOS = 30;
const agoraSeg = Date.now() / 1000;
if (!f.forcar && msgs.some((r) => quem(r) === 'salatiel' && agoraSeg - Number(r.messageTimestamp) < PAUSA_MINUTOS * 60)) return [];

// 4) Monta o histórico em texto (últimas 15 mensagens)
const hora = (r) =>
  new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(
    new Date(Number(r.messageTimestamp) * 1000)
  );
const rotulo = { contato: f.nome || 'Contato', salatiel: 'Salatiel', assistente: 'Você (assistente)' };
const linhas = msgs
  .slice(-15)
  .filter((r) => textoDe(r))
  .map((r) => `[${hora(r)}] ${rotulo[quem(r)]}: ${textoDe(r).slice(0, 500)}`);

// Mensagens novas = as do contato depois da última resposta (sua ou do Salatiel)
const novas = [];
for (let i = msgs.length - 1; i >= 0 && quem(msgs[i]) === 'contato'; i--) {
  if (textoDe(msgs[i])) novas.unshift(textoDe(msgs[i]));
}

return [
  {
    json: {
      numero: f.numero,
      instancia: f.instancia,
      nome: f.nome,
      agora: f.agora,
      historico: linhas.join('\n') || '(sem mensagens anteriores)',
      novas: (novas.length ? novas : [f.texto]).join('\n'),
    },
    pairedItem: 0,
  },
];

